  // Step 1: 모든 URL을 동시에 요청
  let futures = []
  FOR url IN urls {
    let future = fetch_url(url)
    futures = append(futures, future)
  }

  // Step 2: 모든 응답을 기다림
  let responses = []
  FOR future IN futures {
    let html = await future
    responses = append(responses, html)
  }

  // Step 3: 각 HTML 파싱
