  FOR html IN responses {
    let future = parse_html(html)
    parse_futures = append(parse_futures, future)
  }

  // Step 4: 모든 파싱 완료 대기
  let results = []
  FOR future IN parse_futures {
    let data = await future
    results = append(results, data)
  }

  PRINTLN("✅ 크롤링 완료!")
  RETURN results
}

